// @vitest-environment node
import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

const root = join(__dirname, "..");
const readme = readFileSync(join(root, "README.md"), "utf8");

function routes(): string[] {
  return readdirSync(join(root, "api"), { withFileTypes: true })
    .filter((e) => e.isFile() && e.name.endsWith(".ts") && !e.name.endsWith(".test.ts"))
    .map((e) => e.name.replace(/\.ts$/, ""));
}

function envVars(): string[] {
  return readFileSync(join(root, ".env.example"), "utf8")
    .split("\n")
    .map((l) => l.trim())
    .filter((l) => l && !l.startsWith("#"))
    .map((l) => l.split("=")[0].trim())
    .filter(Boolean);
}

describe("README", () => {
  it("names every api route", () => {
    const names = routes();
    expect(names.length).toBeGreaterThan(0);
    for (const name of names) expect(readme).toContain(`/api/${name}`);
  });

  it("names every env var from .env.example", () => {
    const vars = envVars();
    expect(vars).toContain("GEMINI_API_KEY");
    for (const v of vars) expect(readme).toContain(v);
  });

  it("names every GEMINI_MODEL_* var", () => {
    const models = envVars().filter((v) => v.startsWith("GEMINI_MODEL_"));
    expect(models.length).toBeGreaterThan(0);
    for (const v of models) expect(readme).toContain(v);
  });

  it("names the partners", () => {
    for (const word of ["Entire", "Gradium", "Gemini"]) expect(readme).toContain(word);
  });
});

describe("manifest", () => {
  it("parses as JSON with name alltag", () => {
    const manifest = JSON.parse(readFileSync(join(root, "public/manifest.webmanifest"), "utf8")) as {
      name: string;
    };
    expect(manifest.name).toBe("alltag");
  });
});
- `src/voice/useVoice.ts` (`VoiceState = idle | listening | thinking | speaking`): Gradium STT + TTS, used by the Review screen. `thinking` is set between a final transcript and the answer; `speak()` sets `speaking`; `stop()` cuts TTS for barge-in.
- `src/voice/useLive.ts` (`LiveState = idle | connecting | listening | speaking | done | error`): Gemini Live for Noé. Live has no separate thinking phase; the server streams audio as soon as it has it. `done` fires when the model calls the `task_done` tool. `error` switches the Roleplay screen to the text fallback that calls `/api/turn`.
- `correcting` is the `finish()` step in `src/screens/Roleplay.tsx`: it stops the live session, posts every learner line to `/api/correct` in parallel, dedupes the corrections, writes `session.lastExchange` and calls `go("corrections")`.

## Service worker

`vite-plugin-pwa` (workbox `generateSW`) builds `dist/sw.js` with `registerType: "autoUpdate"` (the worker skips waiting and claims clients); `src/main.tsx` registers `/sw.js` itself in production builds, since the plugin's `virtual:pwa-register` would pull in `workbox-window`. It precaches the app shell (`**/*.{js,css,html,svg,woff2}`, files up to 5 MB) and answers navigations with `/index.html`, so the installed app loads with no network. `/api/*` is excluded from the navigate fallback and routed `NetworkOnly`: API responses are never cached, and offline the client falls back to the on-device model instead. The manifest stays `public/manifest.webmanifest` (`manifest: false` in the plugin).

## Origins

On the web the client and `api/` share one origin: `src/lib/api.ts` fetches `/api/<name>` and no CORS is involved. The iOS app (Capacitor, `server.iosScheme: "https"`) loads the bundled build from `https://localhost`, so it is built with `VITE_API_BASE` set to the Vercel host and calls `${VITE_API_BASE}/api/<name>` with `credentials: "omit"`. Every route starts with `applyCors` from `api/_lib/cors.ts`: an `Origin` listed in `ALLOWED_ORIGINS` (exact match, never a wildcard) gets `Access-Control-Allow-Origin` echoed back, preflights end with 204. The browser guard on `/api/gradium-token` and `/api/live-token` (`originAllowed`) accepts the same origin or an allowlisted one and still rejects any other cross-site caller with 403.

